def solve(s, k):
    n = len(s)
    if k == 0:
        return 0
    if s.count("B") == k:
        return 0
    if s.count("B") == 0:
        return 1
    ops = []
    for i in range(1, n+1):
        for c in ["A", "B"]:
            if s[:i].count(c) == k:
                ops.append((i, c))
    return min([len(ops)] + [len(ops) for i, c in ops])

