def solve(maze, start, end):
    n, m = len(maze), len(maze[0])
    visited = [[False] * m for _ in range(n)]
    queue = [(start, 0)]
    while queue:
        node, step = queue.pop(0)
        for neighbor in get_neighbors(node, visited, maze):
            queue.append((neighbor, step + 1))
        visited[node[0]][node[1]] = True
    return step

def get_neighbors(node, visited, maze):
    n, m = len(maze), len(maze[0])
    neighbors = []
    for i in range(max(0, node[0] - 1), min(n, node[0] + 2)):
        for j in range(max(0, node[1] - 1), min(m, node[1] + 2)):
            if not visited[i][j] and maze[i][j] == 0:
                neighbors.append((i, j))
    return neighbors

